// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address target, address asset, address user, uint256 amount) public {
        // Bound amount to avoid overflow in transferFrom
        amount = bound(amount, 0, 1e30);

        // Precondition: set up flash governance config so assertGovernanceApproved can succeed
        c.configureFlashGovernance(asset, amount, 1 days, false);

        // The deployer (address(this)) is the DAO and has flash-enabled ability
        // First ensure state is configured (true in reference, false in mutant)
        c.endConfiguration();
        bool configuredBefore = c.configured();

        // Attempt assertGovernanceApproved as DAO (msg.sender = address(this))
        (bool success, bytes memory data) = address(c).call(
            abi.encodeWithSignature("assertGovernanceApproved(address,address,bool)", user, target, false)
        );

        bool configuredAfter = c.configured();

        // General rule: configured should remain true if the call reverted or succeeded
        // In reference, configured is set to true by endConfiguration and never changes
        // In mutant, configured is set to false by endConfiguration and never changes
        // So after the transaction, configured must be true (as reference always has it)
        assertTrue(configuredAfter == true);
    }
}

